s_of = '' AND (p_subtree IS NULL OR d.tumbler LIKE p_subtree || '.%') AND (p_where IS NULL OR c.metadata @> p_where) AND (p_manifest_where IS NULL OR e.eff @> p_manifest_where) AND (p_manifest_path IS NULL OR e.eff @@ p_manifest_path::jsonpath) AND c.embedding_768 IS NOT NULL ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query LIMIT p_n $$;
